"use client";
import { useEffect, useRef, useState } from "react";
import { useHydratedReducedMotion } from "../../hooks/use-hydrated-reduced-motion";
import { cx } from "../../utils/cx";
import {
  ACTIVITY_RINGS,
  type ActivityRing,
  ActivityRings,
  ActivityRingsCard,
} from "./activity-rings-card";
import { ACTIVITY_DAYS } from "./health-demo-data";
import { ChartFrame, MONTHS, WeekSwitcher } from "./pro-chart";
export interface ActivityDay {
  date: string;
  steps: number;
  rings?: ActivityRing[];
}
export interface MostActiveDaysCardProps {
  title?: string;
  data?: ActivityDay[];
  selectedDate?: Date;
  defaultDate?: Date;
  onDateChange?: (date: Date) => void;
  showActivity?: boolean;
  className?: string;
  headline?: number;
}
const INITIAL_DATE = new Date(2026, 6, 10);
const dayKey = (date: Date) =>
  `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
export function MostActiveDaysCard({
  title = "Most active days",
  data,
  selectedDate,
  defaultDate = INITIAL_DATE,
  onDateChange,
  showActivity = true,
  className,
  headline = 32459,
}: MostActiveDaysCardProps = {}) {
  const [internal, setInternal] = useState(defaultDate),
    selected = selectedDate ?? internal,
    [month, setMonth] = useState(selected.getMonth()),
    scrollRef = useRef<HTMLDivElement>(null),
    year = selected.getFullYear();
  const reduced = useHydratedReducedMotion();
  const scrollToMonth = (next: number) => {
    const target = scrollRef.current?.querySelector<HTMLElement>(
      `[data-month="${next}"]`,
    );
    if (target && scrollRef.current)
      scrollRef.current.scrollTo?.({
        top: Math.max(0, target.offsetTop - 9),
        behavior: reduced ? "auto" : "smooth",
      });
  };
  const controlledMonth = selectedDate?.getMonth();
  useEffect(() => {
    scrollToMonth(controlledMonth ?? defaultDate.getMonth());
  }, [year, controlledMonth, reduced]);
  const select = (date: Date) => {
    setInternal(date);
    onDateChange?.(date);
  };
  const currentDay = data?.find((d) => d.date === dayKey(selected));
  return (
    <div
      className={cx(
        "grid w-full min-w-0 gap-4",
        showActivity && "md:grid-cols-2",
        className,
      )}
    >
      <ChartFrame
        title={title}
        value={currentDay?.steps ?? headline}
        suffix="total steps"
        height={330}
        padding="inset"
        className="rounded-[20px]"
        action={
          <WeekSwitcher
            compact
            className="w-[128px] dark:border-background-primary-default"
            label={new Date(year, month).toLocaleDateString("en-US", {
              month: "long",
            })}
            onPrevious={() => scrollToMonth((month + 11) % 12)}
            onNext={() => scrollToMonth((month + 1) % 12)}
          />
        }
      >
        <div className="min-h-0 w-full flex-1 overflow-hidden rounded-2lg bg-background-inner-default px-2.5">
          <div
            ref={scrollRef}
            onScroll={(event) => {
              const scroll = event.currentTarget;
              const visibleMonth = [
                ...scroll.querySelectorAll<HTMLElement>("[data-month]"),
              ]
                .filter((node) => node.offsetTop <= scroll.scrollTop + 20)
                .at(-1);
              if (visibleMonth) setMonth(Number(visibleMonth.dataset.month));
            }}
            className="h-full w-full overflow-y-auto overscroll-contain [scrollbar-width:none]"
          >
            <div className="relative flex flex-col gap-4 py-2.5">
              {MONTHS.map((label, m) => {
                const count = new Date(year, m + 1, 0).getDate(),
                  offset = 0;
                return (
                  <div
                    key={label}
                    data-month={m}
                    className="flex flex-col gap-2.5"
                  >
                    <p className="ps-1 text-title-3-medium text-text-primary">
                      {label}
                    </p>
                    <div className="grid grid-cols-7 gap-x-[5px]">
                      {Array.from({ length: offset }, (_, i) => (
                        <span key={`blank-${i}`} />
                      ))}
                      {Array.from({ length: count }, (_, i) => {
                        const date = new Date(year, m, i + 1),
                          key = dayKey(date),
                          entry = data?.find((d) => d.date === key),
                          isSelected = dayKey(selected) === key,
                          sample =
                            ACTIVITY_DAYS[
                              Math.floor(
                                (Date.UTC(year, m, i + 1) -
                                  Date.UTC(year, 0, 1)) /
                                  86400000,
                              )
                            ],
                          rings =
                            entry?.rings ??
                            ACTIVITY_RINGS.map((r, n) => ({
                              ...r,
                              color:
                                n === 0
                                  ? "var(--color-chart-3-active)"
                                  : undefined,
                              progress: data ? 0 : (sample?.[2][n] ?? 0),
                            }));
                        return (
                          <button
                            type="button"
                            key={key}
                            aria-label={date.toLocaleDateString("en-US", {
                              dateStyle: "full",
                            })}
                            aria-pressed={isSelected}
                            onClick={() => select(date)}
                            className={cx(
                              "flex h-[78px] cursor-pointer flex-col items-center justify-center gap-2.5 rounded-2lg border-2 p-2.5 outline-none transition-colors duration-150 ease focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-border-focus-ring",
                              isSelected
                                ? "border-border-button-hover bg-background-primary-default"
                                : "border-transparent hover:bg-background-primary-hover",
                            )}
                          >
                            <span className="text-body-medium whitespace-nowrap text-text-primary">
                              {i + 1}
                            </span>
                            <ActivityRings
                              rings={rings}
                              compact
                              animate={false}
                            />
                          </button>
                        );
                      })}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </ChartFrame>
      {showActivity && (
        <ActivityRingsCard
          title={`Activity for ${selected.toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" })}`}
          rings={currentDay?.rings}
          selectedDate={selected}
        />
      )}
    </div>
  );
}
